# Segnale emesso quando il cristallo viene raccolto
signal collected


func _ready() -> void:
	# Colleghiamo il segnale di ingresso di un corpo fisico
	body_entered.connect(_on_body_entered)


func _on_body_entered(body: Node3D) -> void:
	# Verifichiamo se a entrare è il personaggio del giocatore
	if body is CharacterBody3D:
		collected.emit()
		queue_free() # Rimuove il cristallo dalla scena
","spiegazione":"Lo script di `Area3D` ascolta il segnale `body_entered`. Quando un corpo tridimensionale entra nell'area, controlliamo se si tratta del nostro `CharacterBody3D`. In caso affermativo emettiamo il segnale `collected` e rimuoviamo l'oggetto con `queue_free()`."},{"tipo":"testo","md":"### Oggetti fisici dinamici con RigidBody3D\n\nA differenza di `CharacterBody3D`, le cui posizioni e velocità vengono scritte direttamente nel codice tramite `move_and_slide()`, un nodo **`RigidBody3D`** è totalmente gestito dal motore fisico di Godot. Subisce la gravità, rimbalza, rotola e reagisce agli urti con altri corpi fisici.\n\nPer creare una cassa spingibile sull'isola, usiamo un `RigidBody3D`. Tuttavia, poiché un `CharacterBody3D` per impostazione predefinita attraversa o blocca i corpi rigidi senza muoverli in automatico con la forza appropriata, dobbiamo applicare un impulso alla cassa quando il giocatore le cammina contro."},{"tipo":"passi","titolo":"Creare la scena di una cassa spingibile","passi":["Crea una nuova scena indipendente con radice `RigidBody3D` e rinominala `PushBox`.","Aggiungi un nodo `MeshInstance3D` con un `BoxMesh` di dimensione (1, 1, 1) metri.","Aggiungi un nodo `CollisionShape3D` con una forma `BoxShape3D` di identica dimensione (1, 1, 1).","Nel pannello *Inspector* del nodo radice `PushBox`, imposta `mass` (massa) a un valore adeguato, ad esempio `5.0` kg, in modo che non sia troppo pesante.","Salva la scena come `res://push_box.tscn`."]},{"tipo":"immagine","immagine":"editor-3d","didascalia":"L'area di lavoro 3D con gli assi X (rosso), Y (verde) e Z (blu) usati per orientare i nodi RigidBody3D e Area3D."},{"tipo":"testo","md":"### Far spingere i nodi RigidBody3D dal personaggio\n\nQuando il giocatore cammina contro una cassa (`RigidBody3D`), il metodo `move_and_slide()` del `CharacterBody3D` registra l'avvenuta collisione. Possiamo scorrere le collisioni avvenute nell'ultimo fotogramma ed esercitare una forza spinta sulla cassa tramite il metodo `apply_central_impulse()`."},{"tipo":"codice","linguaggio":"gdscript","codice":"# Da inserire nel metodo _physics_process(delta: float) di player.gd, subito dopo move_and_slide()

# Controlliamo tutte le collisioni avvenute durante il movimento
for i in get_slide_collision_count():
	var collision: KinematicCollision3D = get_slide_collision(i)
	var collider: Object = collision.get_collider()

	# Se l'oggetto urtato è un corpo rigido simulato dalla fisica
	if collider is RigidBody3D:
		# Calcoliamo la direzione della spinta opposta alla normale di collisione
		var push_direction: Vector3 = -collision.get_normal()
		# Mantieni la spinta orizzontale per evitare che la cassa decolli
		push_direction.y = 0.0
		push_direction = push_direction.normalized()

		# Appliciamo un impulso al centro della cassa
		var push_force: float = 3.0
		collider.apply_central_impulse(push_direction * push_force)
","spiegazione":"Attraverso `get_slide_collision_count()` leggiamo i punti di contatto generati da `move_and_slide()`. Se l'oggetto toccato (`collider`) è un `RigidBody3D`, convertiamo la normale di collisione in una direzione d'urto orizzontale e chiamiamo `apply_central_impulse()` per trasferire l'energia del movimento al corpo rigido."},{"tipo":"testo","md":"### Zone d'effetto e Piastre a Pressione\n\nLe aree tridimensionali `Area3D` possono essere usate anche come sensori volumetrici per rilevare quando un oggetto o il giocatore rimangono al loro interno.\n\nEcco i due casi d'uso classici che collegano le casse e il movimento al mondo di gioco:\n* **Zona d'acqua**: Un'area invisibile o semi-trasparente che riduce la velocità di movimento del personaggio quando vi si trova all'interno.\n* **Piastra a pressione**: Un'area posizionata sul pavimento che rileva l'ingresso di casse o del personaggio per aprire un passaggio."},{"tipo":"codice","linguaggio":"gdscript","codice":"extends Area3D

# Script per una piastra a pressione: res://pressure_plate.gd
signal activated
signal deactivated

var objects_inside: int = 0


func _ready() -> void:
	body_entered.connect(_on_body_entered)
	body_exited.connect(_on_body_exited)


func _on_body_entered(body: Node3D) -> void:
	# Contiamo sia il giocatore che le casse fisiche
	if body is CharacterBody3D or body is RigidBody3D:
		objects_inside += 1
		if objects_inside == 1:
			activated.emit()


func _on_body_exited(body: Node3D) -> void:
	if body is CharacterBody3D or body is RigidBody3D:
		objects_inside -= 1
		if objects_inside == 0:
			deactivated.emit()
","spiegazione":"La piastra a pressione tiene traccia del numero di corpi rigidi o personaggi presenti sopra di essa tramite la variabile `objects_inside`. Emette `activated` quando entra il primo oggetto ed `deactivated` solo quando la piastra torna ad essere completamente vuota."},{"tipo":"codice","linguaggio":"gdscript","codice":"extends Area3D

# Script per una zona d'acqua che rallenta: res://water_zone.gd
@export var speed_multiplier: float = 0.4


func _ready() -> void:
	body_entered.connect(_on_body_entered)
	body_exited.connect(_on_body_exited)


func _on_body_entered(body: Node3D) -> void:
	# Se il personaggio ha un metodo o una proprietà per la velocità, la riduciamo
	if body.has_method("apply_speed_modifier"):
		body.apply_speed_modifier(speed_multiplier)


func _on_body_exited(body: Node3D) -> void:
	if body.has_method("apply_speed_modifier"):
		body.apply_speed_modifier(1.0)
","spiegazione":"La zona d'acqua ascolta sia l'ingresso (`body_entered`) sia l'uscita (`body_exited`). Usiamo il duck typing (`has_method`) per verificare che il corpo entrato sappia gestire la modifica temporanea della velocità."},{"tipo":"attenzione","md":"Non modificare mai direttamente la proprietà `position` o `global_position` di un `RigidBody3D` dentro il metodo `_process()` o `_physics_process()`. Spostare manualmente un corpo rigido interrompe la simulazione fisica e può causare compenetrazioni o comportamenti anomali. Per spostare un `RigidBody3D`, usa sempre gli impulsi (`apply_central_impulse()`) o modificane la velocità lineare (`linear_velocity`)."},{"tipo":"riepilogo","md":"- I concetti di fisica 2D (`Area2D`, maschere di collisione, segnali `body_entered`) si applicano esattamente allo stesso modo al 3D usufruendo dei nodi con suffisso `3D`.\n- `Area3D` rileva l'ingresso e l'uscita di corpi tridimensionali senza ostacolarne il movimento: è ideale per collezionabili, zone ambientali e piastre a pressione.\n- `RigidBody3D` viene simulato direttamente dal motore fisico di Godot, subendo gravità, forze e collisioni.\n- `CharacterBody3D` può spingere i nodi `RigidBody3D` analizzando i dati di collisione resi da `move_and_slide()` e applicando una forza tramite `apply_central_impulse()`."}]}
